  const BASE_HP = { grunt: 60, runner: 40, wisp: 50, brute: 150, splitter: 90, mender: 70 };
  const SPEED = { grunt: 10, runner: 20, wisp: 12, brute: 6, splitter: 8, mender: 8, splitling: 12 };
  const BOUNTY = { grunt: 4, runner: 4, wisp: 6, brute: 9, splitter: 6, mender: 7, splitling: 1 };
  const LEAK = { grunt: 1, runner: 1, wisp: 2, brute: 3, splitter: 2, mender: 2, splitling: 1 };
  const AIR = { grunt: 0, runner: 0, wisp: 1, brute: 0, splitter: 0, mender: 0, splitling: 0 };
