function createStrategy() {
  const plan = [
    { slot: 2, type: "bolt" }, { slot: 4, type: "cannon" }, { slot: 6, type: "bolt" },
    { slot: 7, type: "frost" }, { slot: 8, type: "lance" }, { slot: 10, type: "flak" },
    { slot: 11, type: "bolt" }, { slot: 12, type: "cannon" }, { slot: 13, type: "frost" },
    { slot: 14, type: "lance" }, { slot: 9, type: "flak" }, { slot: 5, type: "bolt" },
    { slot: 0, type: "cannon" }, { slot: 1, type: "frost" }, { slot: 3, type: "bolt" },
    { slot: 15, type: "bolt" }
  ];
  const costs = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  return {
    plan(s) {
      const actions = [];
      let gold = s.gold;
      const occupied = {};
      for (const sl of s.slots) {
        if (sl.turret) occupied[sl.slot] = sl.turret;
      }
      for (const p of plan) {
        if (!occupied[p.slot] && gold >= costs[p.type]) {
          actions.push({ op: "build", slot: p.slot, type: p.type });
          gold -= costs[p.type];
          occupied[p.slot] = { type: p.type, tier: 1, spent: costs[p.type] };
        }
      }
      for (const sl of s.slots) {
        if (actions.length >= 32) break;
        const t = sl.turret || occupied[sl.slot];
        if (!t || !sl.turret) continue;
        const cost = t.tier === 1 ? costs[t.type] : costs[t.type] * 2;
        if (t.tier < 3 && gold >= cost) {
          actions.push({ op: "upgrade", slot: sl.slot });
          gold -= cost;
        }
      }
      return actions;
    },
    target(t, candidates) {
      let best = null, bestScore = -1;
      for (const e of candidates) {
        let score = (e.remaining < 250 ? 10000 : 0) + (e.type === "mender" ? 3000 : 0) +
          (e.type === "brute" ? 2000 : 0) + (e.type === "splitter" ? 1000 : 0) +
          e.maxHp - e.hp - e.remaining * 0.01;
        if (e.slowed) score -= 5;
        if (score > bestScore) { bestScore = score; best = e; }
      }
      return best ? best.id : candidates[0].id;
    }
  };
}

