  // === RENDER / STATE ===
  let playbackState = STATE_COUNTDOWN;
  let simTime = 0;
  let playbackSpeed = 1.0;
  let countdownElapsed = 0;
  let holdElapsed = 0;
  let firstRaf = true;
  let lastFrameMs = null;
  let lastFilter = "";

  function showCountdownText(text) {
    countdownEl.style.display = "block";
    countdownEl.textContent = text;
  }
  function hideCountdown() {
    countdownEl.style.display = "none";
    countdownEl.textContent = "";
  }
  function setPlayingUi() {
    iconPause.style.display = "inline";
    iconPlay.style.display = "none";
    btnToggle.setAttribute("aria-label", "Pause");
  }
  function setPausedUi() {
    iconPause.style.display = "none";
    iconPlay.style.display = "inline";
    btnToggle.setAttribute("aria-label", "Play");
  }
  function updateCountdownUi() {
    if (playbackState !== STATE_COUNTDOWN) return;
    const text = countdownElapsed < 1 ? "3" : (countdownElapsed < 2 ? "2" : "1");
    if (countdownEl.textContent !== text || countdownEl.style.display !== "block") {
      showCountdownText(text);
    }
  }
  function setScrubberValue(value) {
    const s = typeof value === "string" ? value : value.toFixed(3);
    if (scrubber.value !== s) scrubber.value = s;
  }

  function renderCurrent() {
    if (!frames.length) return;
    const solved = solveTick(simTime);
    const current = frameAt(solved.tick);
    if (!current) return;
    const next = frameAt(Math.min(solved.tick + 1, maxFrameTick));
    const motionTime = fallTick >= 0 ? Math.min(simTime, fallTime) : simTime;
    const fallAge = fallTick >= 0 ? simTime - fallTime : -1;

    updateKeep(current, motionTime);
    updateTurrets(current, motionTime);
    setCameraForTime(simTime);
    renderEnemies(current, next, solved.alpha, motionTime);
    renderEffects(motionTime, simTime, fallAge);
    hud.update(current, motionTime);

    const gray = fallTick >= 0 && simTime > fallTime
      ? smoothstep(fallTime, fallTime + 1.0, simTime) * 0.95
      : 0;
    const filterCss = gray > 0.002 ? "grayscale(" + gray.toFixed(3) + ")" : "none";
    if (filterCss !== lastFilter) {
      stage.style.filter = filterCss;
      lastFilter = filterCss;
    }

    const W = Math.max(1, window.innerWidth);
    const H = Math.max(1, window.innerHeight);
    renderer.setViewport(0, 0, W, H);
    renderer.clear(true, true, true);
    renderer.setViewport(sceneViewport.x, sceneViewport.y, sceneViewport.w, sceneViewport.h);
    renderer.render(scene, camera);
    renderer.setViewport(0, 0, W, H);
    renderer.clearDepth();
    renderer.render(hudScene, hudCamera);
  }

  function advanceTime(dt) {
    if (playbackState === STATE_COUNTDOWN) {
      countdownElapsed += dt;
      if (countdownElapsed >= COUNTDOWN_DURATION) {
        hideCountdown();
        playbackState = STATE_PLAYING;
        setPlayingUi();
        simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
        setScrubberValue(simTime);
        if (simTime >= DURATION) {
          simTime = DURATION;
          setScrubberValue(DURATION.toFixed(3));
          playbackState = STATE_ENDED;
          setPausedUi();
        }
      } else {
        updateCountdownUi();
      }
    } else if (playbackState === STATE_PLAYING) {
      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
      setScrubberValue(simTime);
      if (simTime >= DURATION) {
        simTime = DURATION;
        setScrubberValue(DURATION.toFixed(3));
        playbackState = STATE_ENDED;
        setPausedUi();
      }
    } else if (playbackState === STATE_REFIRE_HOLD) {
      holdElapsed += dt;
      if (holdElapsed >= REFIRE_HOLD_DURATION) {
        playbackState = STATE_PLAYING;
        setPlayingUi();
      }
    }
  }

  function endHoldWithoutStart() {
    if (playbackState === STATE_COUNTDOWN || playbackState === STATE_REFIRE_HOLD) {
      hideCountdown();
      simTime = 0;
      setScrubberValue("0");
      playbackState = STATE_PAUSED;
      setPausedUi();
    }
  }

  btnToggle.addEventListener("click", () => {
    if (playbackState === STATE_PLAYING) {
      playbackState = STATE_PAUSED;
      setPausedUi();
    } else if (playbackState === STATE_COUNTDOWN || playbackState === STATE_REFIRE_HOLD) {
      endHoldWithoutStart();
    } else if (playbackState === STATE_PAUSED) {
      playbackState = STATE_PLAYING;
      setPlayingUi();
    } else if (playbackState === STATE_ENDED) {
      hideCountdown();
      simTime = 0;
      setScrubberValue("0");
      playbackState = STATE_PLAYING;
      setPlayingUi();
    }
    renderCurrent();
    audio.update(playbackState, simTime);
  });

  btnRefire.addEventListener("click", () => {
    hideCountdown();
    simTime = 0;
    playbackState = STATE_REFIRE_HOLD;
    holdElapsed = 0;
    setScrubberValue("0");
    setPlayingUi();
    audio.reset();
    renderCurrent();
    audio.update(playbackState, simTime);
  });

  scrubber.addEventListener("input", () => {
    if (playbackState === STATE_COUNTDOWN || playbackState === STATE_REFIRE_HOLD) {
      hideCountdown();
    }
    const v = parseFloat(scrubber.value);
    simTime = clamp(Number.isFinite(v) ? v : 0, 0, DURATION);
    playbackState = STATE_PAUSED;
    setPausedUi();
    renderCurrent();
    audio.update(playbackState, simTime);
  });

  for (const btn of speedButtons) {
    btn.addEventListener("click", () => {
      const v = parseFloat(btn.dataset.speed);
      if (!Number.isFinite(v)) return;
      playbackSpeed = v;
      for (const b of speedButtons) {
        const active = b === btn;
        b.classList.toggle("is-active", active);
        b.setAttribute("aria-checked", active ? "true" : "false");
      }
    });
  }

  window.addEventListener("resize", applyResize);

  // Initial resting scene, rendered before the first animation callback.
  applyResize();
  showCountdownText("3");
  updateCountdownUi();
  audio.update(playbackState, simTime);

  function animationLoop(timestamp) {
    requestAnimationFrame(animationLoop);
    if (firstRaf) {
      lastFrameMs = timestamp;
      firstRaf = false;
      // The countdown clock begins on this first callback after the resting
      // scene has already been rendered.
      renderCurrent();
      audio.update(playbackState, simTime);
      return;
    }
    const rawDt = (timestamp - lastFrameMs) / 1000;
    lastFrameMs = timestamp;
    const dt = Math.min(Math.max(0, rawDt), 0.1);
    advanceTime(dt);
    renderCurrent();
    audio.update(playbackState, simTime);
  }
  requestAnimationFrame(animationLoop);
})();

