// Coordinate-ascent search over final slot->type composition using the real sim.
const fs = require("fs");
eval(fs.readFileSync("/private/tmp/pcd-sbx-deepseek-v4.1-flash-max-r1-woarhq0y/tmp/rampart-dev/sim.js", "utf8"));
const { makeScripted } = require("./scripted.js");

const ALL_TYPES = ["cannon", "flak", "bolt", "frost", "lance"];
const ORDER = [4, 3, 12, 14, 9, 8, 6, 11, 13, 0, 1, 2, 7, 5, 10, 15];
const SEEDS = [];
for (let s = 1; s <= 24; s++) SEEDS.push(s);

function buildsFor(assign) { return ORDER.map(slot => ({ slot, type: assign[slot] })); }
function evalAssign(assign, opts, seeds) {
  const builds = buildsFor(assign);
  let sum = 0;
  for (const seed of seeds) sum += rampartSimulate(makeScripted(builds, opts), seed, 12020).score;
  return sum / seeds.length;
}

const baseOpts = { buildPolicy: "strict", upMode: "tier", covPow: 1, tgt: { cannon: "value", flak: "valueUrgent", bolt: "front" }, flakK: 80 };
const mode = process.argv[2] || "tier";
if (mode !== "tier") {
  baseOpts.upMode = mode;
  if (mode === "value") baseOpts.tgt = { cannon: "valueUrgent", flak: "valueUrgent", bolt: "front" };
}
const cache = new Map();
function keyOf(a) { return a.join(","); }
function meanOf(a) {
  const k = keyOf(a);
  if (cache.has(k)) return cache.get(k);
  const m = evalAssign(a, baseOpts, SEEDS);
  cache.set(k, m);
  return m;
}
let assign = [];
for (let i = 0; i < 16; i++) assign[i] = "cannon";
assign[12] = "flak"; assign[13] = "bolt"; assign[14] = "flak"; assign[15] = "flak";
let best = meanOf(assign);
console.log("start", best.toFixed(3), assign.join(","));
for (let pass = 0; pass < 4; pass++) {
  let improved = false;
  for (let slot = 0; slot < 16; slot++) {
    const cur = assign[slot];
    let bestType = cur, bestVal = meanOf(assign);
    for (const t of ALL_TYPES) {
      if (t === cur) continue;
      const cand = assign.slice(); cand[slot] = t;
