function scriptById(id) {
  const re = new RegExp('<script id="' + id + '">([\\s\\S]*?)<\\/script>');
  const m = html.match(re);
  if (!m) throw new Error("missing script " + id);
  return m[1];
}
const strategyText = scriptById("rampart-strategy");
const simText = scriptById("rampart-sim");
console.log("strategy chars", strategyText.length, "sim chars", simText.length);
const topFn = strategyText.match(/^\s*function\s+[A-Za-z_$][\w$]*\s*\(/gm) || [];
console.log("top-level function declarations in strategy:", topFn.length, topFn.map(x=>x.trim()));
const forbiddenStrategy = /(window|document|THREE|Math\.random|Date\b|performance\b|fetch\(|XMLHttpRequest|WebSocket|setTimeout|setInterval|requestAnimationFrame)/.exec(strategyText);
